using Object=UnityEngine.Object;
namespace EchoStation.SalvageNext.Tests
{
    public sealed class NextEffectsTests
    {
        Scene old,scene;bool background;float scale;int baseline;GameObject root;SalvageMotor motor;SalvageEcho echo;SalvageEchoCoordinator brain;NextFaultSparks effects;Volume volume;VolumeProfile profile;ScriptableRendererFeature ao;bool aoActive;
        [Test]public void SparkPrefabAndNewSceneHaveExplicitLocalAndGlobalBudgets()
        {
            var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(NextEffects.PrefabPath).GetComponent<ParticleSystem>();Assert.DoesNotThrow(()=>ParticleEffectPool.Validate(prefab,2));Assert.That(prefab.main.maxParticles,Is.EqualTo(8));Assert.That(prefab.emission.burstCount,Is.EqualTo(1));Assert.That(prefab.GetComponent<ParticleSystemRenderer>().sharedMaterial.shader.name,Is.EqualTo("Universal Render Pipeline/Particles/Unlit"));var renderer=AssetDatabase.LoadAssetAtPath<UniversalRendererData>(NextRendering.RendererPath);Assert.That(renderer.rendererFeatures.Count(f=>f is ScanWaveFeature),Is.EqualTo(1));Assert.That(ParticleBudget.MaximumConcurrentSystems,Is.EqualTo(4));Assert.That(ParticleBudget.MaximumParticlesPerSystem,Is.EqualTo(64));
        }
        IEnumerator Boot()
        {
            background=Application.runInBackground;Application.runInBackground=true;scale=Time.timeScale;baseline=ParticleBudget.ActiveSystems;old=SceneManager.GetActiveScene();scene=EditorSceneManager.LoadSceneInPlayMode(NextLayout.ScenePath,new LoadSceneParameters(LoadSceneMode.Additive));while(!scene.isLoaded)yield return null;SceneManager.SetActiveScene(scene);yield return null;root=scene.GetRootGameObjects().Single(r=>r.name=="ES_SalvageNext_World");motor=root.GetComponentInChildren<SalvageMotor>();motor.enabled=false;var input=motor.GetComponent<PlayerInputReader>();input.SetApplicationFocus(true);input.SetPointerCaptured(true);input.SetUiBlocked(false);echo=root.GetComponentInChildren<SalvageEcho>();brain=echo.GetComponent<SalvageEchoCoordinator>();brain.enabled=false;echo.enabled=false;Assert.That(brain.Initialize(),Is.True);brain.AutomaticWarnings=false;brain.ResetBase(IntentKind.Wait);effects=root.GetComponentInChildren<NextFaultSparks>();effects.Automatic=false;
        }
        static IEnumerator Frame(){int frame=Time.frameCount;while(Time.frameCount==frame)yield return null;}
        [UnityTest,Timeout(120000)]public IEnumerator TwoSystemPoolEnforcesSixteenParticlesReusesAndRestoresBudget()
        {
            yield return new EnterPlayMode();yield return Boot();var pool=effects.Pool;var camera=motor.View.GetComponent<Camera>();motor.RestorePose(new Vector3(24,.1f,16),0,0);camera.transform.LookAt(effects.Position(0));Assert.That(pool.Capacity,Is.EqualTo(2));var systems=pool.GetComponentsInChildren<ParticleSystem>(true);Assert.That(systems.Length,Is.EqualTo(2));Assert.That(effects.TryBurst(0,out var first),Is.True);Assert.That(effects.TryBurst(0,out var second),Is.True);Assert.That(effects.TryBurst(0,out _),Is.False);foreach(var system in systems)system.Simulate(.1f,false,true,false);int peak=pool.LiveParticleCount;Assert.That(peak,Is.InRange(1,16));Assert.That(ParticleBudget.ActiveSystems-baseline,Is.EqualTo(2));Assert.That(first.Stop(),Is.True);Assert.That(effects.TryBurst(0,out var replacement),Is.True);Assert.That(first.Stop(),Is.False);Assert.That(pool.ActiveCount,Is.EqualTo(2));Assert.That(second.Stop(),Is.True);Assert.That(replacement.Stop(),Is.True);
            for(int i=0;i<24;i++){Assert.That(effects.TryBurst(0,out var lease),Is.True);Assert.That(lease.Stop(),Is.True);}CollectionAssert.AreEqual(systems,pool.GetComponentsInChildren<ParticleSystem>(true));Assert.That(pool.ActiveCount,Is.Zero);Assert.That(effects.TryBurst(0,out _),Is.True);var lifetime=System.Diagnostics.Stopwatch.StartNew();while(pool.ActiveCount>0){if(lifetime.Elapsed.TotalSeconds>2){File.WriteAllText(NextEffects.Evidence+"/LifetimeFailure_"+Guid.NewGuid().ToString("N")+".json",new JArray(systems.Select(system=>new JObject{{"alive",system.IsAlive(false)},{"playing",system.isPlaying},{"paused",system.isPaused},{"time",system.time},{"particleCount",system.particleCount},{"loop",system.main.loop}})).ToString());Assert.Fail("Particle did not automatically return within2s");}yield return Frame();}Assert.That(pool.ActiveCount,Is.Zero,"Completed particle was not returned");var input=motor.GetComponent<PlayerInputReader>();input.SetUiBlocked(true);Assert.That(effects.TryBurst(0,out _),Is.False);input.SetUiBlocked(false);Assert.That(input.PointerCaptured,Is.False);input.SetPointerCaptured(true);Assert.That(input.CanPlay,Is.True);var localView=camera.transform.localPosition;camera.transform.position=new Vector3(-50,2,-50);Assert.That(effects.TryBurst(0,out _),Is.False);camera.transform.localPosition=localView;motor.RestorePose(new Vector3(24,.1f,16),0,0);camera.transform.LookAt(effects.Position(0));Assert.That(effects.TryBurst(0,out _),Is.True,"Near burst after far-view restoration");effects.enabled=false;Assert.That(pool.ActiveCount,Is.Zero);Assert.That(ParticleBudget.ActiveSystems,Is.EqualTo(baseline));effects.enabled=true;effects.Automatic=false;Assert.That(pool.Capacity,Is.EqualTo(2));
            File.WriteAllText(NextEffects.Evidence+"/Pool_"+Guid.NewGuid().ToString("N")+".json",new JObject{{"capacity",2},{"particlesPeak",peak},{"systemsReusedAcross24Bursts",true},{"staleLeaseRejected",true},{"autoReturned",true},{"menuFarDenied",true},{"disabledBudgetRestored",true}}.ToString());
        }
        [UnityTest,Timeout(180000)]public IEnumerator ActualNewRoverScanTriggersOneFullscreenPassWithoutScanParticles()
        {
            yield return new EnterPlayMode();yield return Boot();var hub=motor.GetComponent<SalvageCommandHub>();var scanner=echo.GetComponent<SalvageScanner>();scanner.Initialize();var wave=echo.GetComponent<ScanWaveEmitter>();var camera=motor.View.GetComponent<Camera>();var view=camera.GetComponent<ScanWaveView>();Assert.That(view.Source,Is.SameAs(wave));motor.RestorePose(new Vector3(7,.1f,19),90,35);Assert.That(echo.Navigation.TryBind(new Vector3(9,0,17.5f)),Is.True);echo.transform.rotation=Quaternion.identity;Physics.SyncTransforms();Assert.That(hub.PointedId(),Is.EqualTo("cargo_a"));float battery=echo.Battery.Charge;int particles=root.GetComponentsInChildren<ParticleSystem>(true).Length;Assert.That(brain.Command(ScriptCommands.Investigate("cargo_a")),Is.True);var timer=System.Diagnostics.Stopwatch.StartNew();while(!wave.State.Active){Assert.That(timer.Elapsed.TotalSeconds,Is.LessThan(5),scanner.LastError);yield return null;brain.Advance(Mathf.Min(Time.deltaTime,.1f),false);}Assert.That(wave.State.Origin,Is.EqualTo(echo.GetComponent<EchoRig>().ScanOrigin.position));Time.timeScale=0;wave.State.Tick(.3f);
            motor.GetComponent<NextFocus>().enabled=false;root.GetComponent<NextFogField>().enabled=false;foreach(var decor in root.GetComponentsInChildren<InstancedRoomDecor>())decor.enabled=false;foreach(var flicker in root.GetComponentsInChildren<FaultLightFlicker>())flicker.enabled=false;foreach(var light in root.GetComponentsInChildren<Light>())light.enabled=false;volume=root.GetComponentsInChildren<Volume>().Single(v=>v.name=="ES_Next_GlobalVolume");profile=volume.profile;profile.TryGet<FilmGrain>(out var grain);grain.intensity.value=0;profile.TryGet<ChromaticAberration>(out var chromatic);chromatic.intensity.value=0;var renderer=AssetDatabase.LoadAssetAtPath<UniversalRendererData>(NextRendering.RendererPath);ao=renderer.rendererFeatures.Single(f=>f.name.Contains("AmbientOcclusion"));aoActive=ao.isActive;ao.SetActive(false);camera.scene=scene;string id=Guid.NewGuid().ToString("N");Color[] off,on;view.enabled=false;using(var capture=new SalvageFrameCapture(camera))capture.Capture(NextEffects.Evidence+"/Warm_"+id+".png");using(var capture=new SalvageFrameCapture(camera))off=capture.Capture(NextEffects.Evidence+"/ScanOff_"+id+".png");view.enabled=true;using(var capture=new SalvageFrameCapture(camera))on=capture.Capture(NextEffects.Evidence+"/ScanOn_"+id+".png");float difference=SalvageFrameCapture.Difference(off,on);FrameDebuggerEvidence.CaptureResult frame=null;yield return FrameDebuggerEvidence.Capture(()=>{using(var capture=new SalvageFrameCapture(camera))capture.Capture(NextEffects.Evidence+"/ScanCaptured_"+id+".png");},NextEffects.Evidence+"/ScanFD_"+id+".json",value=>frame=value);int passes=frame.events.Count(e=>e.type=="DrawProcedural"&&e.label.Contains("Echo Scan Wave"));Assert.That(difference,Is.GreaterThan(.00001f));Assert.That(passes,Is.EqualTo(1));Assert.That(root.GetComponentsInChildren<ParticleSystem>(true).Length,Is.EqualTo(particles));Assert.That(effects.Pool.ActiveCount,Is.Zero);
            Time.timeScale=scale;timer.Restart();while(!hub.Known.Contains("cargo_a")){Assert.That(timer.Elapsed.TotalSeconds,Is.LessThan(5),scanner.LastError);yield return null;brain.Advance(Mathf.Min(Time.deltaTime,.1f),false);}Assert.That(battery-echo.Battery.Charge,Is.InRange(8,8.7f));Assert.That(motor.GetComponent<SalvageCarry>().Registry.Get("cargo_a").State,Is.EqualTo(CargoState.World));Assert.That(motor.GetComponent<SalvageDelivery>().Count,Is.Zero);wave.State.Cancel();wave.State.Begin(Vector3.zero);wave.State.Cancel();long before=GC.GetAllocatedBytesForCurrentThread();for(int i=0;i<1000;i++){wave.State.Begin(Vector3.zero);wave.State.Tick(.1f);wave.State.Cancel();}long allocated=GC.GetAllocatedBytesForCurrentThread()-before;Assert.That(allocated,Is.Zero);File.WriteAllText(NextEffects.Evidence+"/Scan_"+id+".json",new JObject{{"imageDifference",difference},{"fullscreenPasses",passes},{"scanCreatedParticleSystems",0},{"charged",battery-echo.Battery.Charge},{"cargoStillWorld",true},{"delivered",0},{"stateOperationIterations",1000},{"stateOperationAllocatedBytes",allocated}}.ToString());
        }
        [UnityTearDown]public IEnumerator Cleanup(){if(!Application.isPlaying)yield break;Time.timeScale=scale;if(ao)ao.SetActive(aoActive);if(volume)volume.profile=null;if(profile){foreach(var c in profile.components)if(c)Object.Destroy(c);Object.Destroy(profile);}if(old.IsValid())SceneManager.SetActiveScene(old);if(scene.IsValid()){var op=SceneManager.UnloadSceneAsync(scene);while(op!=null&&!op.isDone)yield return null;}Assert.That(ParticleBudget.ActiveSystems,Is.EqualTo(baseline));Application.runInBackground=background;yield return new ExitPlayMode();}
    }
}
